<script lang="ts">
  import { PortalStateMap } from "./portal-state.svelte";
  import { onMount, type Snippet } from "svelte";

  interface PortalProps {
    name: string;
    children: Snippet;
  }

  let { name, children }: PortalProps = $props();

  onMount(() => {
    PortalStateMap.set(name, children);

    return () => {
      PortalStateMap.delete(name);
    }
  });

</script>
